(()=>{
'use strict';
const STORE='leagueStageToolsV2';
const JOURNEY='leagueJourneyStateV1';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const val=id=>($(id)?.value||'').trim();
const selectedText=id=>{const x=$(id);return x?.options?.[x.selectedIndex]?.text||''};
const checked=name=>[...document.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value);
function load(){try{return JSON.parse(localStorage.getItem(STORE)||'{}')}catch(e){return {}}}
function savePart(key,value){const s=load();s[key]=value;try{localStorage.setItem(STORE,JSON.stringify(s))}catch(e){}return value}
function loadJourney(){try{return JSON.parse(localStorage.getItem(JOURNEY)||'{}')}catch(e){return {}}}
function saveJourney(part){const s=loadJourney();Object.assign(s,part);try{localStorage.setItem(JOURNEY,JSON.stringify(s))}catch(e){}}
function download(name,text){const b=new Blob([text],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),250)}
function list(items,empty='No items yet.'){return items?.length?`<ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<p>${esc(empty)}</p>`}
function pct(n,min=0,max=100){return Math.max(min,Math.min(max,Math.round(n)))}
function supportMode(){return document.body.dataset.supportMode||loadJourney().support||'guided'}
function guidance(q){const mode=supportMode();if(mode==='independent')return `<details class="wizard-help"><summary>Need a hint?</summary><p><strong>Why:</strong> ${esc(q.why)}</p><p><strong>How:</strong> ${esc(q.how)}</p></details>`;if(mode==='supported')return `<div class="wizard-guidance"><p><strong>Why this matters:</strong> ${esc(q.why)}</p><p><strong>Tip:</strong> ${esc(q.how)}</p></div>`;return `<div class="wizard-guidance"><p><strong>Why this matters:</strong> ${esc(q.why)}</p><p><strong>How to respond:</strong> ${esc(q.how)}</p><p class="example-line"><strong>Example:</strong> ${esc(q.example||'')}</p></div>`}
function toolSaved(out,msg='Saved in this browser.'){if(out){const p=document.createElement('p');p.className='local-save-note';p.textContent=msg;out.append(p)}}

// --- Interview Coach ---
if($('interview-person')) $('interview-person').value=(loadJourney().projectLens||'other')==='self'?'self':'learner';
$('interview-form')?.addEventListener('submit',e=>{
 e.preventDefault();const who=val('interview-person'),purpose=val('interview-purpose'),focus=val('interview-focus')||'this learning task';
 const self=who==='self';
 const open=self?`Think about the last time you tried ${focus}. What was happening?`:`Tell me about the last time you tried ${focus}. What was happening?`;
 const q=[open,
  self?`Walk yourself through what you did from the beginning. Where did your approach change?`:`Can you walk me through what you did from the beginning?`,
  `What part feels easiest or most familiar? What makes that part work?`,
  purpose==='strategies'?`What do you usually try when you get stuck? What happens after you try it?`:`Where do you first hesitate, get confused, slow down, or change strategy?`,
  purpose==='context'?`When is this easier, and when is it harder? What is different about those situations?`:`Can you show or describe one specific example?`,
  `If you could change one thing about the learning experience—not name a product—what would you want to be different?`
 ];
 const cautions=[];if(who==='teacher')cautions.push('Ask for examples of student work or behavior, not only the teacher’s interpretation of the cause.');if(who==='self')cautions.push('Self-study can miss habits you no longer notice. Ask a teammate or advisor to observe one attempt if possible.');
 const out=$('interview-plan');out.innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Interview plan</span><h3>Listen before you design</h3><p>Use these as starters. Follow the person’s story instead of asking every question mechanically.</p></div></div><ol class="generated-question-list">${q.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${cautions.length?`<div class="note-box"><strong>Watch for</strong>${list(cautions)}</div>`:''}<div class="tool-actions"><button class="button secondary small" id="download-interview-plan" type="button">Download plan</button></div>`;
 $('interview-notes').hidden=false;const plain='INTERVIEW PLAN\n\n'+q.map((x,i)=>`${i+1}. ${x}`).join('\n');savePart('interview',{who,purpose,focus,questions:q,plain});$('download-interview-plan')?.addEventListener('click',()=>download('league-interview-plan.txt',plain));toolSaved(out);
});
$('interview-synthesize')?.addEventListener('click',()=>{
 const heard=val('interview-heard'),observed=val('interview-observed'),surprise=val('interview-surprise'),unknown=val('interview-unknown');
 const insights={heard,observed,surprise,unknown};savePart('empathyInsights',insights);const out=$('interview-insights');out.innerHTML=`<h3>Empathy insights</h3><div class="synthesis-grid"><p><strong>We heard:</strong> ${esc(heard||'[add repeated ideas]')}</p><p><strong>We observed:</strong> ${esc(observed||'[add observable evidence]')}</p><p><strong>We changed our mind about:</strong> ${esc(surprise||'[add a changed assumption]')}</p><p><strong>We still need to know:</strong> ${esc(unknown||'[add an open question]')}</p></div>`;toolSaved(out);
});

// --- Learning Breakdown Mapper wizard ---
const breakdownQ=[
 {k:'lens',label:'Who is this project trying to help learn?',type:'select',options:[['self','Myself'],['other','Someone else']],why:'The evidence you can collect and the assumptions you need to challenge differ when you study yourself versus another learner.',how:'Choose the learner whose experience is the basis of this project.',example:'Someone else'},
 {k:'challenge',label:'What is the broad learning challenge you are starting with?',type:'textarea',why:'A broad challenge gives you a starting point, but it is usually too large to design for directly.',how:'Name the subject/task and what seems difficult without labeling the learner.',example:'The learner gets graph-scale questions wrong when only some values are labeled.'},
 {k:'task',label:'What is the overall task the learner is trying to do?',type:'textarea',why:'You cannot locate a breakdown until you know the performance the learner is trying to complete.',how:'Use an observable verb: solve, explain, interpret, compare, plan, recall, revise, etc.',example:'Determine the value represented by an unlabeled point on a graph axis.'},
 {k:'steps',label:'What happens step by step?',type:'textarea',why:'The final error may be only a symptom. A task map helps you find the first meaningful point where the process changes.',how:'Put one step per line. Include decisions or representations, not only physical actions.',example:'Read the axis label\nFind two labeled values\nCount the spaces between them\nFind the change in value\nDivide by the number of spaces\nUse the interval to find the target value'},
 {k:'already',label:'What can the learner already do successfully?',type:'textarea',why:'Design should build from existing knowledge and avoid reteaching what is already working.',how:'Name an observed success and the conditions under which it occurs.',example:'The learner identifies the axis and can subtract the two labeled endpoint values.'},
 {k:'breakdown',label:'Where does the process first seem to break down?',type:'textarea',why:'This is the candidate bottleneck your prototype should target.',how:'Describe the learner action, error, hesitation, or strategy at the first meaningful breakdown.',example:'The learner counts labeled points rather than the spaces between them.'},
 {k:'prereq',label:'What knowledge, representation, or strategy might be needed at that point?',type:'textarea',why:'A missing prerequisite or strategy can look like a problem with the larger task.',how:'Name what the learner may need to know or do immediately before the breakdown.',example:'Understand that intervals are the spaces between tick marks, not the tick marks themselves.'},
 {k:'evidence',label:'What evidence supports this explanation?',type:'textarea',why:'A plausible story is not enough. You need evidence from attempts, interviews, work, observation, or verified research.',how:'Name at least two pieces of evidence when possible and note uncertainty.',example:'In two work samples, the learner used 5 as the divisor for 4 spaces; during the interview they said they “count the numbers.”'},
 {k:'access',label:'Could access or presentation be causing some of the difficulty?',type:'select',options:[['checked-none','We checked; no obvious access barrier explains it'],['possible','Yes, an access/presentation issue may contribute'],['notchecked','We have not checked yet']],why:'Reading load, language, visual presentation, pacing, motor interaction, attention, or device access can be mistaken for a knowledge problem.',how:'Choose the most accurate statement. If access may contribute, fix or test that before labeling the learner.',example:'We checked; no obvious access barrier explains it'},
 {k:'success',label:'What observable change would show improvement?',type:'textarea',why:'A design needs a learning target that can be observed, not only a feeling of usefulness.',how:'Describe what the learner should do on a new or realistic task and how much help should be needed.',example:'On a new graph, the learner identifies the number of spaces and calculates the interval accurately without a hint.'},
 {k:'scope',label:'How much of the problem are you trying to address with one prototype?',type:'select',options:[['one','One specific component'],['few','Two closely connected components'],['broad','Several different skills or the whole subject']],why:'A small prototype can only test a small number of assumptions well.',how:'Choose the smallest honest description of your intended scope.',example:'One specific component'}
];
let bIndex=0,bAnswers=load().breakdownAnswers||{};if(!bAnswers.lens)bAnswers.lens=(loadJourney().projectLens||'other')==='self'?'self':'other';
function breakdownInput(q){if(q.type==='select')return `<label for="breakdown-current">${esc(q.label)}</label><select id="breakdown-current">${q.options.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select>`;return `<label for="breakdown-current">${esc(q.label)}</label><textarea id="breakdown-current" placeholder="${esc(q.example)}"></textarea>`}
function renderBreakdown(){if(!$('breakdown-question-host'))return;const q=breakdownQ[bIndex];$('breakdown-progress-label').textContent=`Step ${bIndex+1} of ${breakdownQ.length}`;$('breakdown-progress').max=breakdownQ.length;$('breakdown-progress').value=bIndex+1;$('breakdown-question-host').innerHTML=`<span class="wizard-category">Define</span><h3>${esc(q.label)}</h3>${guidance(q)}${breakdownInput(q)}`;const input=$('breakdown-current');if(bAnswers[q.k])input.value=bAnswers[q.k];$('breakdown-back').disabled=bIndex===0;const submit=$('breakdown-wizard-form').querySelector('button[type=submit]');submit.textContent=bIndex===breakdownQ.length-1?'Analyze the learning breakdown':'Save and continue →';$('breakdown-status').textContent='';}
function analyzeBreakdown(){const a=bAnswers,steps=(a.steps||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);let score=0;const strengths=[],revisions=[],blockers=[];
 if((a.challenge||'').length>=20){score+=8;strengths.push('The starting challenge is described concretely.')}else revisions.push('Write the broad challenge as a complete, observable learning situation.');
 if((a.task||'').length>=12){score+=8;strengths.push('The overall task is observable.')}else revisions.push('Name the overall task using an observable learner action.');
 if(steps.length>=4){score+=14;strengths.push(`The task map contains ${steps.length} steps.`)}else{revisions.push('Add enough steps to show what happens before the final answer.');}
 if((a.already||'').length>=12){score+=10;strengths.push('The map identifies existing learner success.')}else revisions.push('Name what the learner can already do successfully.');
 if((a.breakdown||'').length>=15){score+=15;strengths.push('A candidate first breakdown is named.')}else blockers.push('The first meaningful breakdown is not specific enough yet.');
 if((a.prereq||'').length>=10)score+=7;else revisions.push('Consider the knowledge, representation, or strategy needed immediately before the breakdown.');
 if((a.evidence||'').length>=35){score+=15;strengths.push('The bottleneck explanation is connected to evidence.')}else blockers.push('More evidence is needed before treating the proposed bottleneck as established.');
 if(a.access==='checked-none'){score+=8;strengths.push('The team considered access as an alternative explanation.')}else if(a.access==='possible'){score+=4;revisions.push('Test or reduce the access barrier before deciding how much of the difficulty is a learning breakdown.')}else blockers.push('Check whether access or presentation explains part of the difficulty.');
 if((a.success||'').length>=20){score+=10;strengths.push('The team has an observable success target.')}else blockers.push('Define what observable change would count as improvement.');
 if(a.scope==='one'){score+=12;strengths.push('The prototype scope is focused on one component.')}else if(a.scope==='few'){score+=6;revisions.push('Consider whether the two components can be tested separately.')}else blockers.push('The intended scope is too broad for one prototype.');
 let label='Too broad',cls='fit-blocked',explain='The team is still trying to explain or improve too many things at once.';if(score>=78&&!blockers.length){label='Ready to design';cls='fit-high';explain='You have a specific learner action, mapped breakdown, evidence, and observable target that can guide ideation.'}else if(score>=55&&blockers.length<=2){label='Almost there';cls='fit-medium';explain='The challenge is taking shape, but one or two important decisions need more evidence or a narrower scope.'}
 const subject=a.lens==='self'?'I can already':'The learner can already';const focus=a.lens==='self'?'I have difficulty':'The learner has difficulty';const frame=`${subject} ${a.already||'[existing success]'}, but ${focus} ${a.breakdown||'[specific component]'} when ${a.task||'[task/context]'}. Evidence suggests ${a.prereq||'[possible prerequisite or process]'} may matter. We will explore ways to support ${a.success||'[observable target action]'}.`;
 const result={score,label,steps,strengths,revisions,blockers,frame,answers:a};savePart('breakdown',result);const out=$('breakdown-result');out.innerHTML=`<div class="result-summary ${cls}"><div><span class="result-kicker">Problem-size classification</span><h3>${label}</h3><p>${esc(explain)}</p></div><div class="score-ring">${pct(score)}%</div></div><div class="result-detail-grid grid two"><article class="card"><h3>The learner can already…</h3><p>${esc(a.already||'[not entered]')}</p><h3>The breakdown seems to happen when…</h3><p>${esc(a.breakdown||'[not entered]')}</p></article><article class="card"><h3>Evidence</h3><p>${esc(a.evidence||'[not entered]')}</p><h3>What success would look like</h3><p>${esc(a.success||'[not entered]')}</p></article></div><div class="callout-blue"><strong>Suggested focused framing</strong><p>${esc(frame)}</p></div><div class="grid three"><article class="card"><h3>Strengths</h3>${list(strengths)}</article><article class="card"><h3>Revise next</h3>${list(revisions)}</article><article class="card"><h3>Do not skip</h3>${list(blockers,'No hard blocker identified.')}</article></div><div class="tool-actions"><a class="button primary" href="#evidence-tracker">Next: Check your claims →</a><button class="button secondary small" id="download-breakdown" type="button">Download map</button></div>`;const plain=`LEARNING BREAKDOWN MAP\n${label} — ${score}%\n\nOVERALL TASK\n${a.task||''}\n\nTASK STEPS\n${steps.map((x,i)=>`${i+1}. ${x}`).join('\n')}\n\nCAN ALREADY\n${a.already||''}\n\nBREAKDOWN\n${a.breakdown||''}\n\nEVIDENCE\n${a.evidence||''}\n\nFOCUSED FRAME\n${frame}`;$('download-breakdown')?.addEventListener('click',()=>download('learning-breakdown-map.txt',plain));toolSaved(out);
}
$('breakdown-wizard-form')?.addEventListener('submit',e=>{e.preventDefault();const q=breakdownQ[bIndex],v=val('breakdown-current');if(!v){$('breakdown-status').textContent='Add a response before continuing.';return}bAnswers[q.k]=v;savePart('breakdownAnswers',bAnswers);if(bIndex<breakdownQ.length-1){bIndex++;renderBreakdown()}else analyzeBreakdown()});
$('breakdown-back')?.addEventListener('click',()=>{const q=breakdownQ[bIndex],v=val('breakdown-current');if(v)bAnswers[q.k]=v;if(bIndex>0)bIndex--;renderBreakdown()});renderBreakdown();

// --- Claim & Evidence Tracker ---
let claims=load().claims||[];
function renderClaims(){if(!$('claim-records'))return;$('claim-records').innerHTML=claims.length?claims.map((r,i)=>`<article class="record-card"><span class="record-number">${i+1}</span><h3>${esc(r.claim)}</h3><p><strong>Evidence:</strong> ${esc(r.source)}</p><p><strong>Type:</strong> ${esc(r.typeLabel)} · <strong>Strength:</strong> ${esc(r.strengthLabel)}</p><p><strong>Design implication:</strong> ${esc(r.implication||'[not entered]')}</p>${r.type==='ai'?'<div class="warning-inline">AI suggestion: verify an original source or collect direct evidence before using this as support.</div>':''}</article>`).join(''):'<p class="empty-state">No evidence records yet.</p>'}
$('add-claim')?.addEventListener('click',()=>{const claim=val('claim-text'),source=val('claim-source');if(!claim||!source){$('claim-warning').textContent='Add both the claim and what supports it.';return}const r={claim,source,type:val('claim-type'),typeLabel:selectedText('claim-type'),strength:val('claim-strength'),strengthLabel:selectedText('claim-strength'),implication:val('claim-implication')};claims.push(r);savePart('claims',claims);renderClaims();$('claim-warning').textContent=r.type==='ai'?'Saved as a starting point only. AI output is not evidence until verified.':'Evidence record saved in this browser.';['claim-text','claim-source','claim-implication'].forEach(id=>$(id).value='')});
$('download-claims')?.addEventListener('click',()=>download('claim-evidence-records.txt',claims.map((r,i)=>`RECORD ${i+1}\nCLAIM: ${r.claim}\nEVIDENCE: ${r.source}\nTYPE: ${r.typeLabel}\nSTRENGTH: ${r.strengthLabel}\nDESIGN IMPLICATION: ${r.implication}`).join('\n\n')));renderClaims();

// --- Strategy Explorer ---
const strategies={
 retrieval:{name:'Retrieval practice + spacing',desc:'Ask the learner to bring information to mind instead of only rereading or re-seeing it.',products:['Printable question deck','Partner recall challenge','Low-stakes practice quiz','Short retrieval routine','AI-generated question bank that students curate'],test:'Use a new or delayed recall task and compare accuracy/support needed.',caution:'Do not use pure recall practice when the main problem is conceptual understanding rather than access to learned information.'},
 elaboration:{name:'Elaboration + self-explanation',desc:'Have the learner explain why, connect ideas, justify a step, or generate an example.',products:['Explain-it cards','Teach-back routine','Why/how question deck','Concept connection map','AI conversation that asks for explanations without giving them'],test:'Ask for an explanation or application on a new example and examine whether important relationships appear.',caution:'Novices may need examples or prompts before open-ended self-explanation is productive.'},
 worked:{name:'Worked examples + fading',desc:'Show a model of the process, then gradually remove steps so the learner takes over.',products:['Faded worksheet','Step-strip cards','Worked-example comparison','Human role-play tutor','Guided digital sequence'],test:'Reduce one support at a time and observe whether the learner completes the missing step independently.',caution:'Do not leave all steps visible forever; the support should fade.'},
 error:{name:'Error analysis + targeted feedback',desc:'Help the learner inspect an attempt, locate the error, explain it, and try again.',products:['Find-the-error cards','Correction routine','Annotated examples','Peer debugging challenge','AI coach that asks the learner to diagnose before giving a cue'],test:'Use a new error pattern and track whether the learner identifies and corrects it with less help.',caution:'Feedback should point to a useful next action rather than only mark wrong/correct.'},
 chunking:{name:'Task decomposition + chunking',desc:'Break a complex task into meaningful components and support planning across them.',products:['Step map','Decision checklist','Question-decomposition mat','Sequence card sort','Guided task navigator'],test:'Ask the learner to plan or sequence a fresh task and record where support is still needed.',caution:'Avoid creating so many micro-steps that the learner loses the overall goal.'},
 metacognition:{name:'Metacognitive monitoring + self-regulation',desc:'Prompt the learner to plan, monitor understanding, choose a strategy, and reflect on evidence.',products:['Self-check routine','Confidence-with-reason cards','Strategy chooser','Learning log','Reflection coach'],test:'Observe whether the learner notices a problem and chooses a useful next strategy without being told.',caution:'Reflection prompts must connect to actual task evidence, not vague feelings.'},
 comparison:{name:'Comparison + contrasting cases',desc:'Place examples side by side so the learner must notice the feature that matters.',products:['Card sort','Which-one-and-why challenge','Side-by-side examples','Physical comparison activity','Interactive comparison screen'],test:'Give a new pair and ask the learner to name the critical difference and use it.',caution:'The compared cases must differ on the feature you want the learner to notice.'},
 representation:{name:'Representation interpretation',desc:'Connect symbols, diagrams, graphs, words, objects, or other representations of the same idea.',products:['Representation matching cards','Physical-to-symbolic activity','Annotated diagram routine','Graph/diagram challenge','Multimodal digital activity'],test:'Ask the learner to translate or explain across representations on a new case.',caution:'Adding more representations can increase cognitive load if the connections are not explicit.'},
 transfer:{name:'Varied practice + transfer',desc:'Practice the same underlying idea across meaningfully different examples and contexts.',products:['Mixed example set','Scenario cards','Transfer challenge','Real-world task trail','Adaptive practice set'],test:'Use an unfamiliar context and examine whether the learner recognizes when and how to use the strategy.',caution:'Variation should preserve the underlying structure rather than change everything at once.'},
 comprehension:{name:'Text structure + comprehension monitoring',desc:'Help the learner identify important information, structure, meaning, and when comprehension breaks down.',products:['Annotation routine','Main-idea/evidence cards','Questioning guide','Vocabulary-in-context activity','Reading coach'],test:'Use a new passage and observe whether the learner identifies key structure and notices confusion.',caution:'Do not turn comprehension support into answer extraction.'}
};
function strategyAnalysis(){const b=val('strategy-breakdown'),stage=val('strategy-stage'),action=val('strategy-action'),feedback=val('strategy-feedback'),context=val('strategy-context'),constraints=checked('strategy-constraint'),evidence=val('strategy-evidence');const scores={},reasons={};Object.keys(strategies).forEach(k=>{scores[k]=10;reasons[k]=[]});const add=(k,n,r)=>{scores[k]+=n;if(r)reasons[k].push(r)};const map=(obj,r)=>Object.entries(obj).forEach(([k,n])=>add(k,n,r));
 const bm={recall:{retrieval:38,elaboration:10,transfer:8},explain:{elaboration:38,comparison:15,representation:8},procedure:{worked:32,chunking:30,error:10},error:{error:40,worked:14,metacognition:12},representation:{representation:40,comparison:20,worked:8},transfer:{transfer:40,comparison:15,elaboration:12},monitor:{metacognition:42,error:8},comprehension:{comprehension:40,elaboration:14,metacognition:10}};map(bm[b]||{},`matches the reported breakdown: ${selectedText('strategy-breakdown')}`);
 const am={recall:{retrieval:30},explain:{elaboration:28,comparison:8},compare:{comparison:32,representation:10},sequence:{chunking:28,worked:16},apply:{transfer:30,worked:8},monitor:{metacognition:34},correct:{error:34},interpret:{representation:34,comparison:10}};map(am[action]||{},`directly practices the desired learner action: ${selectedText('strategy-action')}`);
 if(stage==='novice')map({worked:20,chunking:14,representation:10,comprehension:8},'offers stronger initial structure for a novice learner');if(stage==='developing')map({error:14,elaboration:10,comparison:10,transfer:8},'fits a learner who can already complete parts with support');if(stage==='near')map({retrieval:10,metacognition:18,transfer:14,error:8},'supports consistency and independence for a near-independent learner');
 const fm={hints:{error:12,worked:12,chunking:6},explain:{elaboration:16,comparison:8},correctness:{retrieval:8,error:16},reflection:{metacognition:18,transfer:6},model:{worked:20,chunking:8}};map(fm[feedback]||{},`fits the desired feedback: ${selectedText('strategy-feedback')}`);
 const cm={repeated:{retrieval:14,error:8},varied:{transfer:18,comparison:8},one:{worked:8,elaboration:8,representation:8},authentic:{transfer:12,metacognition:8,chunking:6}};map(cm[context]||{},`fits the practice context: ${selectedText('strategy-context')}`);
 if(constraints.includes('reading'))map({representation:8,chunking:5},'can reduce or reorganize reading/language demands');if(constraints.includes('visual'))map({representation:10,comparison:6},'can use multiple representations');if(constraints.includes('pacing'))map({metacognition:8,chunking:6,worked:5},'can support learner-controlled pacing');if(constraints.includes('short'))map({retrieval:7,error:6,comparison:5},'can fit short practice windows');if(constraints.includes('social'))map({elaboration:8,comparison:7,error:5},'works well with dialogue or partner interaction');
 const ranked=Object.keys(scores).map(k=>({k,score:scores[k],reasons:[...new Set(reasons[k])]})).sort((a,b)=>b.score-a.score);const max=ranked[0].score;ranked.forEach(r=>r.fit=pct(55+(r.score/max)*43));const confidence={direct:'High',some:'Moderate',report:'Tentative',assumption:'Low'}[evidence];const cautions=[];if(evidence==='assumption')cautions.push('Your current bottleneck is mostly an assumption. Treat all matches as hypotheses and collect direct evidence before committing.');if(evidence==='report')cautions.push('Add direct observation or learner work before treating the strategy match as strong.');if(constraints.includes('offline'))cautions.push('Prioritize formats that still work without reliable internet.');
 const top=ranked.slice(0,3);savePart('strategy',{top,inputs:{b,stage,action,feedback,context,constraints,evidence}});savePart('lastStrategy',top[0].k);return {top,confidence,cautions};}
$('strategy-form')?.addEventListener('submit',e=>{e.preventDefault();const a=strategyAnalysis();const out=$('strategy-results');out.innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Strategy confidence: ${esc(a.confidence)}</span><h3>Compare these three possibilities</h3><p>Ranked recommendations are starting hypotheses. Discuss the fit and evidence with your advisor.</p></div></div><div class="fit-grid">${a.top.map((r,i)=>{const p=strategies[r.k];return `<article class="fit-card"><div class="fit-card-heading"><span class="fit-badge ${i===0?'fit-high':'fit-medium'}">${r.fit}% fit</span><span>#${i+1}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><p><strong>Why suggested</strong></p>${list(r.reasons)}<p><strong>This could become</strong></p>${list(p.products.slice(0,5))}<p><strong>How to test</strong></p><p>${esc(p.test)}</p><p><strong>Watch for</strong></p><p>${esc(p.caution)}</p></article>`}).join('')}</div>${a.cautions.length?`<div class="warning-box"><strong>Evidence caution</strong>${list(a.cautions)}</div>`:''}<div class="tool-actions"><a class="button primary" href="#resource-inventor">Next: Invent with what you have →</a></div>`;toolSaved(out)});

// --- Resource Inventor ---
const resourceNames={paper:'paper',cards:'index cards',markers:'markers',whiteboard:'a whiteboard',calculator:'a calculator',ruler:'a ruler/protractor',notes:'textbooks or class notes',manipulatives:'objects/manipulatives',computer:'a computer',phone:'a phone/tablet',microbit:'a Micro:bit or device',people:'partners/other people',space:'classroom or school space'};
const strategyLabels={retrieval:'retrieval practice',elaboration:'explanation and elaboration',worked:'worked examples with fading',error:'error analysis and targeted feedback',chunking:'task decomposition and chunking',metacognition:'metacognitive monitoring',comparison:'comparison and contrasting cases',representation:'representation interpretation',transfer:'varied practice and transfer',comprehension:'comprehension monitoring'};
function ideaTemplates(strategy,target,res){const has=x=>res.includes(x),m=res.map(x=>resourceNames[x]).filter(Boolean);const materials=m.slice(0,4).join(', ')||'simple materials you can access';const social=has('people');const tech=has('computer')||has('phone');const t=target||'the target learning action';const low={retrieval:`Create a small set of prompts using ${materials}. The learner attempts ${t} from memory before checking or receiving a cue. Sort missed items into a second round so practice changes based on evidence.`,elaboration:`Use ${materials} to make an “explain why / give an example / connect it” challenge for ${t}. The learner must explain before seeing a model.`,worked:`Create one complete worked example for ${t}, then duplicate it with one step missing, then two steps missing. Use ${materials} so support visibly fades.`,error:`Build several examples with one realistic error related to ${t}. The learner locates the first wrong step, explains why it is wrong, and fixes it before seeing feedback.`,chunking:`Turn ${t} into a sequence or decision map using ${materials}. Let the learner arrange, annotate, or follow the steps, then remove the map gradually.`,metacognition:`Create a short plan–try–check routine for ${t} using ${materials}. The learner predicts difficulty, chooses a strategy, checks evidence, and names the next move.`,comparison:`Use ${materials} to create contrasting examples of ${t}. The learner sorts or compares them and names the feature that matters before calculating or labeling.`,representation:`Build a matching or translation activity using ${materials} where the same idea appears as words, symbols, diagrams, objects, or graphs.`,transfer:`Create three versions of ${t} that look different but use the same underlying idea. Ask the learner to identify what stays the same and when the strategy applies.`,comprehension:`Use ${materials} to mark text structure, key ideas, confusing points, and self-check questions while working on ${t}.`}[strategy];
 const people=social?`Turn the activity into a partner challenge: one person performs or explains ${t}; the partner uses a small cue/feedback script based on ${strategyLabels[strategy]}. Switch roles and compare what changed.`:`Role-play two roles within the team: one person acts as the learner and another as the tool/coach. Simulate how ${strategyLabels[strategy]} would support ${t} before building anything.`;
 const digital=tech?`Use a device only where it adds value: create a small digital or AI-assisted version that produces varied examples, prompts, or feedback for ${t}. Keep the learner responsible for the target thinking and compare it with the low-tech version.`:`Stay low-tech for now: storyboard a digital or AI interaction on paper. One teammate plays the system and another the learner so you can test whether the interaction around ${t} is worth digitizing.`;
 return [{title:'Use what you already have',kind:'Low-tech / physical',text:low},{title:'Make it social',kind:'People / activity',text:people},{title:tech?'Try a digital variation':'Prototype the digital idea without technology',kind:tech?'Digital / AI-assisted':'Paper simulation',text:digital}];}
$('invent-resources')?.addEventListener('click',()=>{const target=val('resource-target'),strategy=val('resource-strategy'),res=checked('available-resource'),other=val('resource-other');if(other)res.push('other');if(!target){$('resource-results').innerHTML='<div class="warning-box">Describe what you are trying to help the learner do first.</div>';return}const ideas=ideaTemplates(strategy,target,res);if(other)ideas[0].text+=` Also consider how you could use ${other}.`;savePart('resourceIdeas',{target,strategy,res,other,ideas});const out=$('resource-results');out.innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Resource Inventor</span><h3>Three directions—not three answers</h3><p>Combine, change, or reject these. The goal is to widen the design space.</p></div></div><div class="grid three">${ideas.map((x,i)=>`<article class="idea-card"><span>${i+1}</span><small>${esc(x.kind)}</small><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></article>`).join('')}</div><div class="note-box"><strong>AI reminder:</strong> If AI helped generate an idea, that does not make the learning strategy evidence-based. Verify the learning logic separately.</div>`;toolSaved(out)});
// prefill last strategy
if($('resource-strategy')){const last=load().lastStrategy;const map={retrieval:'retrieval',elaboration:'elaboration',worked:'worked',error:'error',chunking:'chunking',metacognition:'metacognition',comparison:'comparison',representation:'representation',transfer:'transfer',comprehension:'comprehension'};if(last&&map[last])$('resource-strategy').value=map[last]}

// --- Idea Board ---
$('load-resource-ideas')?.addEventListener('click',()=>{const r=load().resourceIdeas;if(!r?.ideas?.length){$('idea-board-result').innerHTML='<div class="warning-box">Run Resource Inventor first, or write your ideas directly.</div>';return}$('idea-noai').value=r.ideas[0]?.text||'';$('idea-existing').value=r.ideas[0]?.text||'';$('idea-social').value=r.ideas[1]?.text||'';$('idea-ai').value=r.ideas[2]?.text||'';$('idea-board-result').innerHTML='<p class="local-save-note">Loaded Resource Inventor directions. Rewrite them in your own words and make them more specific.</p>'});
$('save-idea-board')?.addEventListener('click',()=>{const fields=[['No AI',val('idea-noai')],['Use what you have',val('idea-existing')],['People/social',val('idea-social')],['AI-supported',val('idea-ai')],['Wild card',val('idea-wild')]],filled=fields.filter(x=>x[1]);savePart('ideaBoard',filled);const out=$('idea-board-result');out.innerHTML=`<h3>${filled.length} ideas saved</h3>${filled.length?`<div class="record-grid">${filled.map((x,i)=>`<article class="record-card"><span class="record-number">${i+1}</span><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p></article>`).join('')}</div>`:'<p>Add at least three different ideas before choosing.</p>'}<div class="callout-blue"><strong>Before Prototype:</strong> Circle at least two ideas worth comparing. Ask which one best fits the learner action, evidence, access, and testability—not which looks most impressive.</div>`;toolSaved(out)});

// --- Product / Choose Your Build ---
const products={
 printable:{name:'Printable resource',path:'A',desc:'Cards, worksheet, guide, organizer, or other printable learning aid.',proto:'Make one page, one card set, or one short interaction sequence.'},
 game:{name:'Physical game',path:'A',desc:'A learning game using cards, objects, movement, or classroom materials.',proto:'Build only enough pieces for one round.'},
 routine:{name:'Practice routine',path:'A',desc:'A repeatable sequence for retrieval, explanation, reflection, feedback, or self-monitoring.',proto:'Write and run one 5–10 minute routine.'},
 activity:{name:'Interactive activity',path:'A',desc:'A hands-on, social, spatial, or classroom activity.',proto:'Role-play or run one target interaction with simple materials.'},
 aicontent:{name:'AI-generated content',path:'A',desc:'AI helps create examples, questions, scenarios, or drafts that students/teachers verify before use.',proto:'Generate a tiny sample, verify every item, and test the final learner-facing activity without depending on AI.'},
 conversation:{name:'Conversational AI',path:'B/C',desc:'A Gem/chatbot-style interaction where responses need to change based on learner input.',proto:'Write a short paper/mock conversation or prompt and test one path before building more.'},
 roleplay:{name:'Role-play simulation',path:'A',desc:'A person, team, or scripted system simulates a situation, perspective, or feedback interaction.',proto:'Write one scenario and one role card for each participant.'},
 aiphysical:{name:'AI-supported physical activity',path:'A/B',desc:'AI helps vary prompts, scenarios, or feedback while the main learning activity stays physical or social.',proto:'Run the physical activity with a teammate manually supplying the “AI” variation first.'},
 multimedia:{name:'Multimedia resource',path:'A',desc:'A short audio, visual, slide, animation, or multimodal explanation/practice resource.',proto:'Create one small segment and test whether the representation improves the target action.'},
 app:{name:'Advanced digital application',path:'D',desc:'A custom app, coded interaction, AI Studio build, API-based system, or other advanced product.',proto:'Create a wireframe or one-function prototype before implementing the full application.'}
};
function productAnalysis(){const action=val('product-action'),feedback=val('product-feedback'),conversation=val('product-conversation'),time=val('product-time'),skill=val('product-skill'),access=val('product-access'),accessNeed=val('product-access-need'),platform=val('product-platform'),data=val('product-data'),priorResources=load().resourceIdeas?.res||[];const scores={},reasons={},block={};Object.keys(products).forEach(k=>{scores[k]=20;reasons[k]=[];block[k]=[]});const add=(keys,n,r)=>keys.forEach(k=>{scores[k]+=n;reasons[k].push(r)});
 const actionMap={practice:[['printable','game','routine'],20],explain:[['activity','roleplay','conversation'],18],steps:[['printable','routine','conversation','app'],15],feedback:[['conversation','routine','app','roleplay'],18],simulate:[['roleplay','activity','conversation','app'],20],create:[['aicontent','multimedia','activity'],18]};if(actionMap[action])add(actionMap[action][0],actionMap[action][1],`fits the learner action: ${selectedText('product-action')}`);
 if(feedback==='fixed')add(['printable','game','routine','activity','multimedia'],14,'fixed or predictable feedback is enough');if(feedback==='some')add(['game','routine','activity','aiphysical','conversation'],10,'some branching or targeted feedback is useful');if(feedback==='adaptive')add(['conversation','app'],24,'the interaction requires highly adaptive feedback');
 if(conversation==='no')add(['printable','game','routine','activity','aicontent','multimedia'],12,'conversation is not required');if(conversation==='yes')add(['conversation','roleplay'],25,'conversation is central to the learning interaction');if(conversation==='maybe')add(['roleplay','conversation','activity'],9,'a conversational form might help but is not yet required');
 if(time==='day'){add(['printable','routine','roleplay','activity'],18,'fits a one-session build window');scores.app-=35;scores.conversation-=8}if(time==='short'){add(['printable','game','routine','activity','aicontent','roleplay'],12,'fits a short build window');scores.app-=15}if(time==='medium')add(['game','activity','conversation','aiphysical','multimedia'],10,'fits a multi-week prototype cycle');if(time==='long')add(['conversation','multimedia','app'],8,'there is time for repeated digital iteration');
 if(skill==='new'){add(['printable','game','routine','activity','roleplay','aicontent'],10,'matches a team new to digital development');scores.app-=25}if(skill==='some')add(['aicontent','conversation','aiphysical','multimedia'],10,'matches some no-code/prompt experience');if(skill==='code')add(['app','conversation'],15,'the team has technical capacity for advanced iteration');
 if(access==='lowtech'){add(['printable','game','routine','activity','roleplay'],20,'supports a required low-tech path');scores.conversation-=15;scores.app-=18;scores.multimedia-=5}if(access==='uncertain'){add(['printable','routine','roleplay'],12,'remains usable under uncertain technology access');scores.conversation-=10;scores.app-=15}if(access==='reliable')add(['conversation','aicontent','aiphysical','multimedia','app'],8,'approved technology access is reliable');
 if(accessNeed==='reading')add(['activity','roleplay','game','multimedia'],8,'can reduce reading load or shift information into another representation');if(accessNeed==='sensory')add(['multimedia','activity','printable'],7,'can support multiple representations when designed accessibly');if(accessNeed==='motor')add(['routine','roleplay','printable'],6,'can avoid precise or rapid input');if(accessNeed==='pacing')add(['routine','printable','conversation'],7,'can support learner-controlled pacing when designed carefully');if(accessNeed==='offline'){add(['printable','game','routine','activity','roleplay'],10,'can function without reliable connectivity');scores.conversation-=8;scores.app-=10;}
 if(priorResources.length){const physical=priorResources.some(x=>['paper','cards','markers','whiteboard','calculator','ruler','notes','manipulatives','people','space'].includes(x)),tech=priorResources.some(x=>['computer','phone','microbit'].includes(x));if(physical)add(['printable','game','routine','activity','roleplay','aiphysical'],7,'uses materials already identified in Resource Inventor');if(tech)add(['aicontent','conversation','multimedia','app'],5,'available devices were identified in Resource Inventor');if(!tech&&access!=='reliable'){scores.conversation-=6;scores.app-=9;}}
 if(platform==='restricted'){['conversation','aicontent','aiphysical','app'].forEach(k=>block[k].push('AI/platform use is restricted for this project.'))}if(platform==='uncertain'){['conversation','app'].forEach(k=>block[k].push('Platform/account approval is not confirmed.'));scores.aicontent-=8;scores.aiphysical-=8}if(platform==='approved')add(['conversation','aicontent','aiphysical','app'],8,'an approved platform/account is available');
 if(data==='yes'){['conversation','app','aicontent','aiphysical'].forEach(k=>block[k].push('The current design depends on personal/sensitive learner data. Redesign to minimize data before using AI/digital services.'))}if(data==='avoid')add(['printable','game','routine','activity','roleplay'],6,'the team can redesign to avoid sensitive data');
 if(skill==='new'&&time==='day')block.app.push('A one-session timeline plus beginner technical experience makes a custom app an unrealistic first prototype.');
 const ranked=Object.keys(products).map(k=>({k,raw:scores[k],blocked:block[k],reasons:[...new Set(reasons[k])]})).sort((a,b)=>a.blocked.length-b.blocked.length||b.raw-a.raw);const max=Math.max(...ranked.filter(r=>!r.blocked.length).map(r=>r.raw),1);ranked.forEach(r=>r.fit=r.blocked.length?0:pct(52+(r.raw/max)*46));return ranked}
$('product-form')?.addEventListener('submit',e=>{e.preventDefault();const idea=val('product-idea');if(idea.length<10){$('product-results').innerHTML='<div class="warning-box">Describe the idea you are comparing first.</div>';return}const ranked=productAnalysis(),top=ranked.filter(r=>!r.blocked.length).slice(0,3),blocked=ranked.filter(r=>r.blocked.length).slice(0,3);const primary=top[0];savePart('productDecision',{idea,ranked,primary:primary?.k});if(primary){let path=products[primary.k].path.startsWith('B')?'b':products[primary.k].path==='D'?'d':'a';saveJourney({buildPath:path})}
 const out=$('product-results');out.innerHTML=`<div class="result-summary ${top.length?'fit-high':'fit-blocked'}"><div><span class="result-kicker">Choose Your Build</span><h3>${top.length?`Start by comparing ${esc(products[top[0].k].name)} with two alternatives`:'Resolve blockers before selecting a build form'}</h3><p>The recommendation is about fit and testability, not technical prestige.</p></div></div>${top.length?`<div class="fit-grid">${top.map((r,i)=>{const p=products[r.k];return `<article class="fit-card"><div class="fit-card-heading"><span class="fit-badge ${i===0?'fit-high':'fit-medium'}">${r.fit}% fit</span><span>Path ${esc(p.path)}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><p><strong>Why it fits</strong></p>${list(r.reasons)}<p><strong>Smallest prototype</strong></p><p>${esc(p.proto)}</p></article>`}).join('')}</div>`:''}${blocked.length?`<div class="warning-box"><strong>Options currently blocked or risky</strong>${blocked.map(r=>`<p><b>${esc(products[r.k].name)}:</b> ${esc(r.blocked.join(' '))}</p>`).join('')}</div>`:''}<div class="callout-blue"><strong>Next:</strong> Select the build path that fits your chosen form, then use Prototype Planner. Prompt Builder is only needed when the learning interaction depends on designed AI conversation.</div>`;toolSaved(out)});

// --- Prototype planner ---
$('generate-prototype')?.addEventListener('click',()=>{const x={question:val('proto-question'),format:selectedText('proto-format'),attempt:val('proto-attempt'),materials:val('proto-materials'),notbuild:val('proto-notbuild'),access:val('proto-access'),test:val('proto-test')};if(!x.question){$('prototype-result').innerHTML='<div class="warning-box">Start with the one question the prototype should answer.</div>';return}savePart('prototype',x);const out=$('prototype-result');out.innerHTML=`<h3>Prototype plan</h3><div class="synthesis-grid"><p><strong>Test question:</strong> ${esc(x.question)}</p><p><strong>Format:</strong> ${esc(x.format)}</p><p><strong>Learner must attempt:</strong> ${esc(x.attempt||'[define productive struggle]')}</p><p><strong>Build with:</strong> ${esc(x.materials||'[materials not entered]')}</p><p><strong>Do not build yet:</strong> ${esc(x.notbuild||'[identify features to postpone]')}</p><p><strong>Access plan:</strong> ${esc(x.access||'[add access plan]')}</p><p><strong>First test:</strong> ${esc(x.test||'[add tester and observation target]')}</p></div><div class="callout-blue"><strong>Low-resolution rule:</strong> If a paper flow, role-play, sample set, or storyboard can answer your test question, use that before investing in a polished build.</div><button class="button secondary small" id="download-prototype" type="button">Download prototype plan</button>`;const plain=Object.entries(x).map(([k,v])=>`${k.toUpperCase()}: ${v}`).join('\n\n');$('download-prototype')?.addEventListener('click',()=>download('prototype-plan.txt',plain));toolSaved(out)});

// --- Prompt Builder ---
const promptQ=[
 {k:'format',label:'What should the AI help create or do?',type:'select',options:['Conversation','Quiz or practice questions','Printable activity','Game or challenge','Role-play or scenario','Study routine','Explanation support','Several different approaches to compare','Something else'],why:'The product format changes the instructions and what the learner must do.',how:'Choose the closest intended output or interaction.',example:'Conversation'},
 {k:'learner',label:'Who is the intended learner?',type:'textarea',why:'The prompt needs the learner’s relevant prior knowledge and context without identifying information.',how:'Describe age/grade only when useful, what they already know, and the situation.',example:'A high-school algebra learner who can use the slope formula when values are labeled.'},
 {k:'challenge',label:'What exact learning breakdown should the interaction support?',type:'textarea',why:'A narrow target prevents the AI from becoming a general tutor that does too much.',how:'Use the focused Define-stage problem rather than the broad topic.',example:'Connect rise/run as a ratio to the visible steepness and direction of a line.'},
 {k:'action',label:'What should the learner do during the interaction?',type:'select',options:['Recall','Explain','Compare','Plan or sequence','Apply or transfer','Monitor and reflect','Inspect and correct an error','Interpret a representation'],why:'Learning depends on learner action, not on how much content the AI produces.',how:'Choose the mental action that should provide evidence of learning.',example:'Explain'},
 {k:'sequence',label:'What should happen first, next, and last?',type:'textarea',why:'A clear interaction sequence reduces inconsistent help and keeps the learner oriented.',how:'Describe opening, learner attempt, hint/feedback, retry, reflection, and stopping point.',example:'Ask for an estimate → learner explains → give one focused cue if needed → learner retries → ask for a consistency check.'},
 {k:'struggle',label:'What must the learner attempt before the AI helps?',type:'textarea',why:'This protects productive struggle and learner agency.',how:'Name the explanation, prediction, calculation, comparison, or strategy choice the learner must make first.',example:'The learner must estimate the interval and explain how many spaces they see before receiving a hint.'},
 {k:'feedback',label:'What feedback should the AI give, and when?',type:'textarea',why:'Feedback should respond to an attempt and point toward a useful next action.',how:'Specify timing and levels such as open question → focused cue → partial example.',example:'After the learner explains, identify one correct idea and one gap; ask a focused question before showing any model.'},
 {k:'resources',label:'What available resources should the interaction use?',type:'textarea',why:'AI can connect to paper, notes, classroom objects, people, or physical activities instead of replacing them.',how:'List resources from Resource Inventor that should become part of the activity.',example:'A ruler, whiteboard, graph cards, and the learner’s own sketch.'},
 {k:'limits',label:'What must the AI NOT do?',type:'textarea',why:'Conversational AI often completes the task when asked directly unless the limits are explicit.',how:'State answer-substitution limits, privacy limits, topic boundaries, and when to ask for a trusted adult.',example:'Do not calculate slope for the learner before an attempt; do not ask for identifying information; admit uncertainty.'},
 {k:'access',label:'What accessibility and participation requirements must it follow?',type:'textarea',why:'The interaction must fit real learners, devices, language, pacing, and response modes.',how:'Specify plain language, multiple response modes, pacing, visual descriptions, low-tech alternatives, or other needs.',example:'Use short sentences, describe visual information in text, accept typed or spoken explanations, and provide a printable equivalent.'},
 {k:'fade',label:'How should support decrease as the learner improves?',type:'textarea',why:'Support that never fades can hide whether the learner can perform independently.',how:'Name the evidence that triggers fewer hints, missing steps, longer wait time, or learner choice.',example:'After two correct guided attempts, stop naming the next step and ask the learner to choose it.'},
 {k:'measure',label:'How will you know whether the interaction helped learning?',type:'textarea',why:'Fluent AI output and positive reactions are not enough. You need observable learner evidence.',how:'Name a new task, target behavior, and amount of support to record.',example:'On a new graph, record whether the learner explains the interval and calculates it accurately with fewer hints.'},
 {k:'options',label:'Should the AI give one approach or help compare multiple approaches?',type:'select',options:['Stay with one designed approach','Offer three different approaches for the team to compare','Offer alternatives only when the learner is stuck'],why:'“Give me options” can expand design thinking, but too many alternatives can overwhelm a learner.',how:'Choose whether variety serves the design purpose.',example:'Stay with one designed approach'}
];
let pIndex=0,pAnswers=load().promptAnswers||{},firstPrompt=load().firstPrompt||'',draft1='';
const cross=load();if(!pAnswers.challenge&&cross.breakdown?.frame)pAnswers.challenge=cross.breakdown.frame;if(!pAnswers.resources&&cross.resourceIdeas){const rr=(cross.resourceIdeas.res||[]).map(x=>resourceNames[x]||x);if(cross.resourceIdeas.other)rr.push(cross.resourceIdeas.other);pAnswers.resources=rr.join(', ')}
function promptInput(q){if(q.type==='select')return `<label for="stage-prompt-current">Your answer</label><select id="stage-prompt-current">${q.options.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`;return `<label for="stage-prompt-current">Your answer</label><textarea id="stage-prompt-current" placeholder="${esc(q.example)}"></textarea>`}
function renderPromptQ(){if(!$('stage-prompt-question'))return;const q=promptQ[pIndex];$('stage-prompt-progress-label').textContent=`Question ${pIndex+1} of ${promptQ.length}`;$('stage-prompt-progress').max=promptQ.length;$('stage-prompt-progress').value=pIndex+1;$('stage-prompt-question').innerHTML=`<span class="wizard-category">Prompt design</span><h3>${esc(q.label)}</h3>${guidance(q)}${promptInput(q)}`;const input=$('stage-prompt-current');if(pAnswers[q.k])input.value=pAnswers[q.k];$('stage-prompt-back').disabled=pIndex===0;const submit=$('stage-prompt-form').querySelector('button[type=submit]');submit.textContent=pIndex===promptQ.length-1?'Build Draft 1':'Save and continue →';$('stage-prompt-status').textContent=''}
function buildPrompt(a){return `ROLE\nAct as a learning-support tool. Your job is to support the learner’s thinking, not replace it.\n\nPRODUCT / INTERACTION FORMAT\n${a.format||''}\n\nINTENDED LEARNER\n${a.learner||''}\n\nTARGET LEARNING BREAKDOWN\n${a.challenge||''}\n\nLEARNER ACTION\n${a.action||''}\n\nINTERACTION SEQUENCE\n${a.sequence||''}\n\nPRODUCTIVE STRUGGLE\nBefore giving help, require: ${a.struggle||''}\n\nFEEDBACK\n${a.feedback||''}\n\nAVAILABLE RESOURCES\nUse these when useful: ${a.resources||''}\n\nBOUNDARIES AND LIMITS\n${a.limits||''}\n\nACCESSIBILITY AND PARTICIPATION\n${a.access||''}\n\nFADING\n${a.fade||''}\n\nEVIDENCE OF LEARNING\n${a.measure||''}\n\nOPTIONS MODE\n${a.options||''}\n\nGENERAL BEHAVIOR\n- Ask before telling when the learner can make a meaningful attempt.\n- Ask the learner to show or explain thinking.\n- Prefer graduated hints over immediate answers.\n- Give specific feedback tied to the learner’s attempt.\n- Acknowledge uncertainty and do not invent sources.\n- Avoid fixed learning-style claims.\n- Do not request unnecessary personal information.\n- Stay within the defined learning component.`}
$('begin-prompt-wizard')?.addEventListener('click',()=>{firstPrompt=val('prompt-first');if(!firstPrompt){alert('Write the prompt you would try first. The point is to compare your natural first attempt with the guided version.');return}savePart('firstPrompt',firstPrompt);$('prompt-start').hidden=true;$('prompt-wizard').hidden=false;renderPromptQ()});
$('stage-prompt-form')?.addEventListener('submit',e=>{e.preventDefault();const q=promptQ[pIndex],v=val('stage-prompt-current');if(!v){$('stage-prompt-status').textContent='Add a response before continuing.';return}pAnswers[q.k]=v;savePart('promptAnswers',pAnswers);if(pIndex<promptQ.length-1){pIndex++;renderPromptQ();return}draft1=buildPrompt(pAnswers);savePart('promptDraft1',draft1);const out=$('prompt-compare');out.hidden=false;out.innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Compare your thinking</span><h3>Your first prompt → Guided Draft 1</h3><p>The builder did not invent the learning design. It organized the decisions you made.</p></div></div><div class="compare-prompts"><article><h3>Your first prompt</h3><pre>${esc(firstPrompt)}</pre></article><article><h3>Guided Draft 1</h3><pre>${esc(draft1)}</pre></article></div><div class="callout-blue"><strong>What changed?</strong><p>Look for decisions that became explicit: learner, exact breakdown, learner action, interaction sequence, productive struggle, feedback, resources, limits, accessibility, fading, and evidence of learning. Which of these did your first prompt leave vague?</p></div><div class="tool-actions"><button class="button secondary small" id="download-draft1" type="button">Download Draft 1</button></div>`;$('download-draft1')?.addEventListener('click',()=>download('guided-prompt-draft-1.txt',draft1));$('prompt-test-cycle').hidden=false;toolSaved(out,'Draft 1 saved in this browser. Test it before making Draft 2.')});
$('stage-prompt-back')?.addEventListener('click',()=>{const q=promptQ[pIndex],v=val('stage-prompt-current');if(v)pAnswers[q.k]=v;if(pIndex>0)pIndex--;renderPromptQ()});
$('make-prompt-draft2')?.addEventListener('click',()=>{const worked=val('prompt-test-worked'),failed=val('prompt-test-failed'),learning=val('prompt-test-learning'),revise=val('prompt-test-revise');if(!revise){$('prompt-draft2').innerHTML='<div class="warning-box">Record what you will change before creating Draft 2.</div>';return}const base=draft1||load().promptDraft1||buildPrompt(pAnswers);const d2=`${base}\n\nREVISION FROM TESTING\nWhat worked: ${worked}\nWhat failed or was inconsistent: ${failed}\nEvidence about learner thinking: ${learning}\nChange for Draft 2: ${revise}\n\nApply the revision above while preserving the learning target, productive struggle, accessibility requirements, and evidence plan.`;savePart('promptDraft2',d2);const out=$('prompt-draft2');out.innerHTML=`<h3>Draft 2</h3><pre>${esc(d2)}</pre><div class="tool-actions"><button class="button secondary small" id="download-draft2" type="button">Download Draft 2</button><a class="button primary small" href="student-test.html#testing-tool">Take this to testing →</a></div>`;$('download-draft2')?.addEventListener('click',()=>download('guided-prompt-draft-2.txt',d2));toolSaved(out,'Draft 2 saved. Continue iterating after each meaningful test.')});

// --- Testing & revision ---
let tests=load().tests||[];
function renderTests(){if(!$('test-records'))return;$('test-records').innerHTML=tests.length?tests.map((r,i)=>`<article class="record-card"><span class="record-number">${i+1}</span><h3>${esc(r.version||`Test ${i+1}`)}</h3><p><strong>What the person did:</strong> ${esc(r.behavior)}</p><p><strong>Confusion/help:</strong> ${esc(r.confusion)}</p><p><strong>Learning evidence:</strong> ${esc(r.learning)}</p><p><strong>Access/usability:</strong> ${esc(r.access)}</p><p><strong>Revision:</strong> ${esc(r.revision)}</p></article>`).join(''):'<p class="empty-state">No test records yet.</p>'}
$('make-test-plan')?.addEventListener('click',()=>{const x={who:selectedText('test-who'),question:val('test-question'),task:val('test-task'),success:val('test-success'),watch:val('test-watch'),stop:val('test-stop')};if(!x.question||!x.task){$('test-plan-result').innerHTML='<div class="warning-box">Add the test question and exact task first.</div>';return}savePart('testPlan',x);const caut=val('test-who')==='learner'?'Confirm advisor approval, permissions, privacy, and accessibility before intended-learner testing.':val('test-who')==='peer'?'Peer testing can check clarity and interaction, but may not show impact for a different intended learner.':'Use this test only for the claims it can support.';const out=$('test-plan-result');out.innerHTML=`<h3>Focused test plan</h3><div class="synthesis-grid"><p><strong>Tester:</strong> ${esc(x.who)}</p><p><strong>Question:</strong> ${esc(x.question)}</p><p><strong>Task:</strong> ${esc(x.task)}</p><p><strong>Success evidence:</strong> ${esc(x.success||'[define observable evidence]')}</p><p><strong>Watch for:</strong> ${esc(x.watch||'[add observation targets]')}</p><p><strong>Pause/stop when:</strong> ${esc(x.stop||'[define stopping rule]')}</p></div><div class="note-box">${esc(caut)}</div>`;toolSaved(out)});
$('add-test')?.addEventListener('click',()=>{const r={version:val('test-version'),behavior:val('test-behavior'),confusion:val('test-confusion'),learning:val('test-learning'),access:val('test-access'),revision:val('test-revision')};if(!r.behavior||!r.revision){alert('Record what the tester did and what you will revise.');return}tests.push(r);savePart('tests',tests);renderTests();['test-version','test-behavior','test-confusion','test-learning','test-access','test-revision'].forEach(id=>$(id).value='')});
$('download-tests')?.addEventListener('click',()=>download('testing-revision-log.txt',tests.map((r,i)=>`TEST ${i+1} — ${r.version}\nBEHAVIOR: ${r.behavior}\nCONFUSION: ${r.confusion}\nLEARNING EVIDENCE: ${r.learning}\nACCESS: ${r.access}\nREVISION: ${r.revision}`).join('\n\n')));renderTests();

// --- Share builder ---
$('build-share-story')?.addEventListener('click',()=>{const f=id=>val(id);const x={challenge:f('share-challenge'),learned:f('share-learned'),learning:f('share-learning'),ai:f('share-ai'),design:f('share-design'),evidence:f('share-evidence'),testing:f('share-testing'),revision:f('share-revision'),demo:f('share-demo'),limits:f('share-limits'),next:f('share-next'),access:f('share-access')};if(!x.challenge||!x.design||!x.demo){$('share-result').innerHTML='<div class="warning-box">Add the challenge, what you built, and the focused demo before generating the outline.</div>';return}savePart('shareStory',x);const out=$('share-result');out.innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Sharing-event outline</span><h3>Tell the learning-design story, then demo one meaningful interaction</h3></div></div><ol class="presentation-outline"><li><strong>The challenge</strong><p>${esc(x.challenge)}</p></li><li><strong>What we learned from people and evidence</strong><p>${esc(x.learned||'[add interview/research insight]')}</p></li><li><strong>What we learned about learning</strong><p>${esc(x.learning||'[name the learning idea your team now understands better]')}</p></li><li><strong>What we learned about AI</strong><p>${esc(x.ai||'[explain AI role, limits, verification, or why you did not use AI]')}</p></li><li><strong>Our design and why</strong><p>${esc(x.design)}</p><p><em>Evidence/learning science:</em> ${esc(x.evidence||'[add design rationale]')}</p></li><li><strong>Testing and revision</strong><p>${esc(x.testing||'[add what happened]')}</p><p><em>We changed:</em> ${esc(x.revision||'[add revision]')}</p></li><li><strong>Focused demo</strong><p>${esc(x.demo)}</p></li><li><strong>Limit + next step</strong><p>${esc(x.limits||'[name one limitation]')}</p><p>${esc(x.next||'[name next improvement]')}</p></li></ol><div class="callout-blue"><strong>Demo backup:</strong><p>${esc(x.access||'Prepare screenshots, a paper flow, or another accessible backup.')}</p></div><button class="button secondary small" id="download-share" type="button">Download presentation outline</button>`;const plain=Object.entries(x).map(([k,v])=>`${k.toUpperCase()}: ${v}`).join('\n\n');$('download-share')?.addEventListener('click',()=>download('sharing-event-outline.txt',plain));toolSaved(out)});

function updatePromptGate(){const sec=document.querySelector('[data-ai-prompt-section]');if(!sec)return;let gate=sec.querySelector('.prompt-gate');const path=loadJourney().buildPath||'';if(!gate){gate=document.createElement('div');gate.className='prompt-gate';sec.insertBefore(gate,sec.querySelector('.interactive-tool'));}const tool=sec.querySelector('.interactive-tool');if(path==='b'||path==='c'){gate.innerHTML='<strong>Prompt Builder unlocked for this build path.</strong><p>Your prototype depends on designed AI behavior, so use the guided prompt cycle below.</p>';tool.hidden=false;}else{gate.innerHTML=`<strong>${path==='a'?'Prompt Builder is probably not needed for Path A.':path==='d'?'Use Prompt Builder only if your advanced build includes generative AI behavior.':'Choose a build path first.'}</strong><p>You can still open it if your learning interaction truly depends on conversational AI.</p><button class="button secondary small" type="button" data-open-prompt>Open Prompt Builder anyway</button>`;tool.hidden=true;gate.querySelector('[data-open-prompt]')?.addEventListener('click',()=>{tool.hidden=false;gate.querySelector('[data-open-prompt]').remove();});}}
document.querySelectorAll('[data-build-path]').forEach(b=>b.addEventListener('click',()=>setTimeout(updatePromptGate,20)));updatePromptGate();

// Restore some saved inputs and cross-tool prefill when useful
const saved=load();
if($('resource-target')&&saved.breakdown?.answers?.success)$('resource-target').value=saved.breakdown.answers.success;
if($('product-idea')&&saved.ideaBoard?.length)$('product-idea').value=saved.ideaBoard[0][1];
if($('proto-question')&&saved.productDecision?.idea)$('proto-question').value=`Can this prototype show whether ${saved.productDecision.idea} supports the target learner action?`;

})();
